func (stream *captureMatchStream) finish() error {
	if err := stream.ctx.Err(); err != nil {
		return err
	}
	if stream.lines < stream.maxLines {
		stream.drain(true)
	}
	return nil
}

type capturedMatchEvidence struct {
	matched bool
	terms   []string
	binary  bool
	err     error
}

// The observer retains at most one bit per query term per acquired file. In
// particular, arbitrary case variants on an oversized line cannot grow memory.
type capturePreselectionObserver struct {
	enabled   bool
	mu        sync.Mutex
	prototype captureMatchStream
	terms     []string
	matcher   searchTermMatcher
	records   map[string]capturedMatchEvidence
}

func newCapturePreselectionObserver(ctx context.Context, patterns, terms []string) (*capturePreselectionObserver, error) {
	stream, err := newCaptureMatchStream(ctx, patterns, 32, nil)
	if err != nil {
		return nil, err
	}
	return &capturePreselectionObserver{prototype: *stream, terms: append([]string(nil), terms...), matcher: newSearchTermMatcher(terms), records: map[string]capturedMatchEvidence{}}, nil
}

func (observer *capturePreselectionObserver) factory(path string) (io.Writer, func(error)) {
	observer.mu.Lock()
	enabled := observer.enabled
	observer.mu.Unlock()
	if !enabled {
		return nil, nil
	}
	stream := observer.prototype
	seen := make([]bool, len(observer.terms))
	stream.emit = func(text string) {
		for index, matched := range observer.matcher.match(text) {
			seen[index] = seen[index] || matched
		}
	}
	return &stream, func(err error) {
		if err == nil {
			err = stream.finish()
		}
		evidence := capturedMatchEvidence{matched: stream.matched, binary: stream.binary, err: err}
		for index, matched := range seen {
			if matched {
				evidence.terms = append(evidence.terms, observer.terms[index])
			}
		}
		observer.mu.Lock()
		observer.records[path] = evidence
		observer.mu.Unlock()
	}
}

func (observer *capturePreselectionObserver) evidence(path string) (capturedMatchEvidence, bool) {
	observer.mu.Lock()
	defer observer.mu.Unlock()
	evidence, ok := observer.records[path]
	return evidence, ok
}

func (observer *capturePreselectionObserver) activate() {
	observer.mu.Lock()
	observer.enabled = true
	observer.mu.Unlock()
}
package sem

import (
	"context"
	"strings"

	"github.com/entireio/entire-graph/internal/gitutil"
)

// capturedPreselectionMatches samples fixed-string matches from the operation's
// reader. It never asks Git to reopen source content. Like Git's -m option, the
// budget counts matching lines, not substrings; -o selects nonoverlapping,
// leftmost-longest matches. Only distinct matched strings need be retained for
// the downstream term-presence reduction.
func capturedPreselectionMatches(ctx context.Context, source sourceContext, tracked, patterns []string, maxLines int, observers ...*capturePreselectionObserver) ([]gitutil.GrepMatch, int, error) {
	if len(observers) > 0 && observers[0] != nil {
		observers[0].activate()
	}
	prototype, err := newCaptureMatchStream(ctx, patterns, maxLines, nil)
	if err != nil {
		return nil, 0, err
	}
	terms := make([]string, len(patterns))
	for index, pattern := range patterns {
		terms[index] = strings.ToLower(pattern)
	}
	if len(observers) > 0 && observers[0] != nil {
		terms = observers[0].terms
	}
	termMatcher := newSearchTermMatcher(terms)
	allowed := make(map[string]bool, len(source.paths))
	for _, path := range source.paths {
		allowed[path] = true
	}
	eligible := make([]string, 0, len(tracked))
	for _, path := range tracked {
		if allowed[path] {
			eligible = append(eligible, path)
		}
	}
	attributes, err := source.capturedDiffAttributes(ctx, eligible)
	if err != nil {
		return nil, 0, err
	}
	matches := make([]gitutil.GrepMatch, 0)
	reads := 0
	for _, path := range tracked {
		if err := ctx.Err(); err != nil {
			return nil, reads, err
		}
		if !allowed[path] {
			continue
		}
		content, ok := source.read(path)
		if len(observers) > 0 && observers[0] != nil {
			if evidence, observed := observers[0].evidence(path); observed {
				if evidence.err != nil {
					return nil, reads, evidence.err
				}
				reads++
				attribute := attributes[path]
				if !attribute.Binary && (attribute.Text || !evidence.binary) {
					if evidence.matched && len(evidence.terms) == 0 {
						matches = append(matches, gitutil.GrepMatch{Path: path})
					}
					for _, term := range evidence.terms {
						matches = append(matches, gitutil.GrepMatch{Path: path, Text: term})
					}
				}
				continue
			}
		}
		if !ok {
			continue
		}
		reads++
		stream := *prototype
		seen := make([]bool, len(terms))
		stream.emit = func(text string) {
			for index, matched := range termMatcher.match(text) {
				seen[index] = seen[index] || matched
			}
		}
		if _, err := stream.Write([]byte(content)); err != nil {
			return nil, reads, err
		}
		if err := stream.finish(); err != nil {
			return nil, reads, err
		}
		attribute := attributes[path]
		if !attribute.Binary && (attribute.Text || !stream.binary) {
			if stream.matched {
				matches = append(matches, gitutil.GrepMatch{Path: path})
			}
			for index, matched := range seen {
				if matched {
					matches = append(matches, gitutil.GrepMatch{Path: path, Text: terms[index]})
				}
			}
		}

	}
	return matches, reads, nil
}
