				seen[index] = seen[index] || matched
			}
			all := true
			for _, matched := range seen {
				all = all && matched
			}
			saturated[match.Path] = all
			termMatches[match.Path] = seen
			return nil
		}
		tracked, trackedErr := gitutil.ListIndexFiles(ctx, source.absRepo)
