// prepareSource resolves repository identity, lists the source files, and
// builds a per-file content reader without loading any content.
func prepareSource(ctx context.Context, repo string, options ProviderSnapshotOptions) (sourceContext, error) {
	if options.captured != nil {
		borrowed := *options.captured
		borrowed.close = nil
		if len(options.OnlyFiles) > 0 {
			allowed := make(map[string]bool, len(options.OnlyFiles))
			for _, path := range options.OnlyFiles {
				allowed[filepath.ToSlash(filepath.Clean(path))] = true
			}
			borrowed.paths = nil
			for _, path := range options.captured.paths {
				if allowed[path] {
					borrowed.paths = append(borrowed.paths, path)
				}
			}
		}
		return borrowed, nil
	}

	if options.ExtractionReuse || options.Compiler != nil || options.captureInputs {
		capturedPolicy, err := ensureProviderCachePolicy(repo, options)
		if err != nil {
			return sourceContext{}, fmt.Errorf("capture operation policy: %w", err)
		}
		options = capturedPolicy
	}
	absRepo, err := filepath.Abs(repo)
	if err != nil {
		return sourceContext{}, err
	}
	key := "local/" + filepath.Base(absRepo)
	commit := ""
	tree := ""
	var headErr error
	ctx, metadataSafe := newGitMetadataValidation(ctx, absRepo)
	if metadataSafe {
		key = repoKey(ctx, absRepo)
		commit, tree, headErr = resolveCommittedHEAD(ctx, absRepo)
	} else {
		headErr = gitMetadataRefusalError(absRepo)
	}

	// The provider is local-only. NoNetwork is accepted to make that contract
	// explicit for callers that enforce no-egress provider execution.
	_ = options.NoNetwork
	committedRevision := ""
	if !options.Worktree && headErr == nil {
		committedRevision = commit
	}
	opened, err := openSource(ctx, absRepo, committedRevision, sourceOptions{
		ignoreFiles:            options.IgnoreFiles,
		includeFiles:           options.IncludeFiles,
		cachePolicy:            options.cachePolicy,
		maxReadBytes:           resolveMaxParseBytes(options.MaxParseBytes),
		maxFiles:               options.MaxFiles,
		trackRepoIgnored:       options.trackRepoIgnored,
		capture:                options.ExtractionReuse || options.Compiler != nil || options.captureInputs,
		captureObserverFactory: options.captureObserverFactory,
	})
	if err != nil {
		return sourceContext{}, err
	}
	paths := opened.paths
	if len(options.OnlyFiles) > 0 {
		allowed := make(map[string]bool, len(options.OnlyFiles))
		for _, filePath := range options.OnlyFiles {
			allowed[filepath.ToSlash(filepath.Clean(filePath))] = true
		}
		filtered := paths[:0]
		for _, filePath := range paths {
			if allowed[filepath.ToSlash(filePath)] {
				filtered = append(filtered, filePath)
			}
		}
		paths = filtered
	}
	if opened.prime != nil {
		if err := opened.prime(paths); err != nil {
			if opened.close != nil {
				err = errors.Join(err, opened.close())
			}
			return sourceContext{}, err
		}
	}

	var extraction *extractionCache
	if options.ExtractionReuse {
		extraction = &extractionCache{ctx: ctx, directory: options.ExtractionCacheDir, repository: absRepo + "\x00" + key, build: extractionBuildIdentity()}
	}
	if options.ExtractionReuse || options.Compiler != nil || options.captureInputs {
		if committedRevision == "" && options.cachePolicy != nil {
			opened.read = capturedPolicyContentReader(absRepo, options.cachePolicy, opened.read)
		}
		opened = captureOpenedSource(ctx, opened, extraction)
	}
	if extraction != nil {
		originalClose := opened.close
		opened.close = func() error {
			extraction.flush()
			if originalClose != nil {
				return originalClose()
			}
			return nil
		}
	}
	warnings := append([]ProviderWarning(nil), opened.warnings...)
	if options.Worktree {
		warnings = append(warnings, ProviderWarning{
			Code:                 "W_WORKTREE_SNAPSHOT",
			Severity:             "warning",
			EffectOnCompleteness: "snapshot records are read from the working tree because --worktree was requested",
		})
	} else if headErr != nil {
		warnings = append(warnings, ProviderWarning{
			Code:                 "E_NO_GIT_HEAD",
			Severity:             "warning",
			EffectOnCompleteness: "snapshot records are read from the working tree because no HEAD tree is available",
			Detail:               headErr.Error(),
		})
	}
