func prepareSource(ctx context.Context, repo string, options ProviderSnapshotOptions) (sourceContext, error) {
	if options.captured != nil {
		borrowed := *options.captured
		borrowed.close = nil
		if len(options.OnlyFiles) > 0 {
			allowed := make(map[string]bool, len(options.OnlyFiles))
			for _, path := range options.OnlyFiles {
				allowed[filepath.ToSlash(filepath.Clean(path))] = true
			}
			borrowed.paths = nil
			for _, path := range options.captured.paths {
				if allowed[path] {
					borrowed.paths = append(borrowed.paths, path)
				}
			}
		}
		return borrowed, nil
	}

	if options.ExtractionReuse || options.Compiler != nil || options.captureInputs {
		capturedPolicy, err := ensureProviderCachePolicy(repo, options)
		if err != nil {
			return sourceContext{}, fmt.Errorf("capture operation policy: %w", err)
		}
		options = capturedPolicy
	}
	absRepo, err := filepath.Abs(repo)
	if err != nil {
		return sourceContext{}, err
	}
	key := "local/" + filepath.Base(absRepo)
	commit := ""
	tree := ""
	var headErr error
	ctx, metadataSafe := newGitMetadataValidation(ctx, absRepo)
	if metadataSafe {
		key = repoKey(ctx, absRepo)
		commit, tree, headErr = resolveCommittedHEAD(ctx, absRepo)
	} else {
		headErr = gitMetadataRefusalError(absRepo)
	}

