package sem

import (
	"context"
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// Capture reuse must replay the independent alias pass after the ordinary-term
// sample is exhausted. The target ties four earlier files on "common" alone,
// so its late alias is the only evidence that can admit it to the four-file
// validation pool when MaxIndexedFiles is one.
func TestSearchExtractionReusePreservesLateAliasPreselection(t *testing.T) {
	repo := t.TempDir()
	git(t, repo, "init")
	git(t, repo, "config", "user.name", "Entire Graph Test")
	git(t, repo, "config", "user.email", "graph@example.com")

	common := strings.Repeat("// common\n", 32)
	for index := 0; index < 4; index++ {
		write(t, repo, fmt.Sprintf("a_decoy_%d.go", index), fmt.Sprintf("package p\n%sfunc Decoy%d() {}\n", common, index))
	}
	write(t, repo, "z_target.go", "package p\n"+common+"func readInt() {}\n")
	for index := 0; index < minGitGrepPreselectionFiles+8; index++ {
		write(t, repo, fmt.Sprintf("m_filler_%05d.go", index), fmt.Sprintf("package p\nfunc Filler%05d() {}\n", index))
	}
	git(t, repo, "add", ".")
	git(t, repo, "commit", "-m", "late alias capture fixture")

	baseline, err := SearchRepository(context.Background(), repo, "fixture", "integer common", SearchOptions{
		Worktree: true, Profile: ProfileSyntaxOnly, TopK: 5, MaxIndexedFiles: 1,
		DisableCache: true, CacheDir: t.TempDir(),
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(baseline.Results) == 0 || baseline.Results[0].FilePath != "z_target.go" || baseline.Results[0].SymbolName != "readInt" {
		t.Fatalf("ordinary preselection lost the late alias target: %#v", baseline.Results)
	}

	reuse, err := SearchRepository(context.Background(), repo, "fixture", "integer common", SearchOptions{
		Worktree: true, Profile: ProfileSyntaxOnly, TopK: 5, MaxIndexedFiles: 1,
		ExtractionReuse: true, CacheDir: t.TempDir(),
	})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(reuse.Results, baseline.Results) {
		t.Fatalf("capture reuse changed late-alias results:\nbaseline=%#v\nreuse=%#v", baseline.Results, reuse.Results)
	}
}

