package sem

import (
	"bytes"
	"context"
	"io"
	"os"
	"regexp"
	"strings"
	"sync"
	"unicode/utf8"
)

// captureMatchStream observes a descriptor without retaining the file. The
// caller reduces emitted substrings to query-term presence, so storage is
// independent of source length and the number of matches on one long line.
type captureMatchStream struct {
	ctx             context.Context
	matcher         *regexp.Regexp
	emit            func(string)
	window          int
	buffer          string
	lines, maxLines int
	lineMatched     bool
	matched         bool
	sniffed         int
	binary          bool
}

func newCaptureMatchStream(ctx context.Context, patterns []string, maxLines int, emit func(string)) (*captureMatchStream, error) {
	locale := ""
	for _, name := range []string{"LC_ALL", "LC_CTYPE", "LANG"} {
		if locale = os.Getenv(name); locale != "" {
			break
		}
	}
	asciiFold := locale == "" || locale == "C" || locale == "POSIX"
	quoted := make([]string, 0, len(patterns))
	window := 1
	for _, pattern := range patterns {
		if pattern == "" {
			continue
		}
		quotedPattern := regexp.QuoteMeta(pattern)
		if asciiFold {
			var fixed strings.Builder
			for _, character := range pattern {
				if character >= 'A' && character <= 'Z' {
					character += 'a' - 'A'
				}
				if character >= 'a' && character <= 'z' {
					fixed.WriteRune('[')
					fixed.WriteRune(character)
					fixed.WriteRune(character - 'a' + 'A')
					fixed.WriteRune(']')
				} else {
					fixed.WriteString(regexp.QuoteMeta(string(character)))
				}
			}
			quotedPattern = fixed.String()
		}
		quoted = append(quoted, quotedPattern)
		// Case folding can change UTF-8 width. Four bytes per rune bounds
		// every spelling accepted by the fixed-string regular expression.
		window = max(window, utf8.RuneCountInString(pattern)*utf8.UTFMax)
	}
	expression := "(?:" + strings.Join(quoted, "|") + ")"
	if !asciiFold {
		expression = "(?i)" + expression
	}
	matcher, err := regexp.Compile(expression)
	if err != nil {
		return nil, err
	}
	matcher.Longest()
	if maxLines <= 0 {
		maxLines = 32
	}
	stream := &captureMatchStream{ctx: ctx, matcher: matcher, emit: emit, window: window, maxLines: maxLines}
	if len(quoted) == 0 {
		stream.lines = maxLines
	}
	return stream, nil
}

func (stream *captureMatchStream) Write(data []byte) (int, error) {
	count := len(data)
	if stream.sniffed < 8000 {
		prefix := data[:min(len(data), 8000-stream.sniffed)]
		stream.binary = stream.binary || bytes.IndexByte(prefix, 0) >= 0
		stream.sniffed += len(prefix)
	}
	for len(data) > 0 {
		if err := stream.ctx.Err(); err != nil {
			return count - len(data), err
		}
		if stream.lines >= stream.maxLines {
			return count, nil
		}
		part := data[:min(len(data), 32<<10)]
		data = data[len(part):]
		for len(part) > 0 {
			end := bytes.IndexByte(part, '\n')
			if end < 0 {
				stream.buffer += string(part)
				stream.drain(false)
				break
			}
			stream.buffer += string(part[:end])
			stream.drain(true)
			if stream.lineMatched {
				stream.lines++
			}
			stream.lineMatched = false
			part = part[end+1:]
			if stream.lines >= stream.maxLines {
				stream.buffer = ""
				break
			}
		}
	}
	return count, nil
}

func (stream *captureMatchStream) drain(final bool) {
	for len(stream.buffer) > 0 {
		safe := len(stream.buffer) - stream.window
		if !final && safe < 0 {
			return
		}
		match := stream.matcher.FindStringIndex(stream.buffer)
		if match == nil {
			if final {
				stream.buffer = ""
			} else {
				stream.buffer = stream.buffer[safe:]
			}
			return
		}
		if !final && match[0] > safe {
			stream.buffer = stream.buffer[match[0]:]
			return
		}
		stream.lineMatched = true
		stream.matched = true
		stream.emit(stream.buffer[match[0]:match[1]])
		stream.buffer = stream.buffer[match[1]:]
	}
}

func (stream *captureMatchStream) finish() error {
	if err := stream.ctx.Err(); err != nil {
		return err
	}
	if stream.lines < stream.maxLines {
		stream.drain(true)
	}
	return nil
}

type capturedMatchEvidence struct {
	matched bool
	terms   []string
	binary  bool
	err     error
}

// The observer retains at most one bit per query term per acquired file. In
// particular, arbitrary case variants on an oversized line cannot grow memory.
type capturePreselectionObserver struct {
	enabled   bool
	mu        sync.Mutex
	prototype captureMatchStream
	terms     []string
	matcher   searchTermMatcher
	records   map[string]capturedMatchEvidence
}

func newCapturePreselectionObserver(ctx context.Context, patterns, terms []string) (*capturePreselectionObserver, error) {
	stream, err := newCaptureMatchStream(ctx, patterns, 32, nil)
	if err != nil {
		return nil, err
	}
	return &capturePreselectionObserver{prototype: *stream, terms: append([]string(nil), terms...), matcher: newSearchTermMatcher(terms), records: map[string]capturedMatchEvidence{}}, nil
}

func (observer *capturePreselectionObserver) factory(path string) (io.Writer, func(error)) {
	observer.mu.Lock()
	enabled := observer.enabled
	observer.mu.Unlock()
	if !enabled {
		return nil, nil
	}
	stream := observer.prototype
	seen := make([]bool, len(observer.terms))
	stream.emit = func(text string) {
		for index, matched := range observer.matcher.match(text) {
			seen[index] = seen[index] || matched
		}
	}
	return &stream, func(err error) {
		if err == nil {
			err = stream.finish()
		}
		evidence := capturedMatchEvidence{matched: stream.matched, binary: stream.binary, err: err}
		for index, matched := range seen {
			if matched {
				evidence.terms = append(evidence.terms, observer.terms[index])
			}
		}
		observer.mu.Lock()
		observer.records[path] = evidence
		observer.mu.Unlock()
	}
}

func (observer *capturePreselectionObserver) evidence(path string) (capturedMatchEvidence, bool) {
	observer.mu.Lock()
	defer observer.mu.Unlock()
	evidence, ok := observer.records[path]
	return evidence, ok
}

func (observer *capturePreselectionObserver) activate() {
	observer.mu.Lock()
	observer.enabled = true
	observer.mu.Unlock()
}
package sem

import (
	"context"
	"strings"

	"github.com/entireio/entire-graph/internal/gitutil"
)

// capturedPreselectionMatches samples fixed-string matches from the operation's
// reader. It never asks Git to reopen source content. Like Git's -m option, the
// budget counts matching lines, not substrings; -o selects nonoverlapping,
// leftmost-longest matches. Only distinct matched strings need be retained for
// the downstream term-presence reduction.
func capturedPreselectionMatches(ctx context.Context, source sourceContext, tracked, patterns []string, maxLines int, observers ...*capturePreselectionObserver) ([]gitutil.GrepMatch, int, error) {
	if len(observers) > 0 && observers[0] != nil {
		observers[0].activate()
	}
	prototype, err := newCaptureMatchStream(ctx, patterns, maxLines, nil)
	if err != nil {
		return nil, 0, err
	}
	terms := make([]string, len(patterns))
	for index, pattern := range patterns {
		terms[index] = strings.ToLower(pattern)
	}
	if len(observers) > 0 && observers[0] != nil {
		terms = observers[0].terms
	}
	termMatcher := newSearchTermMatcher(terms)
	allowed := make(map[string]bool, len(source.paths))
	for _, path := range source.paths {
		allowed[path] = true
	}
	eligible := make([]string, 0, len(tracked))
	for _, path := range tracked {
		if allowed[path] {
			eligible = append(eligible, path)
		}
	}
	attributes, err := source.capturedDiffAttributes(ctx, eligible)
	if err != nil {
		return nil, 0, err
	}
	matches := make([]gitutil.GrepMatch, 0)
	reads := 0
	for _, path := range tracked {
		if err := ctx.Err(); err != nil {
			return nil, reads, err
		}
		if !allowed[path] {
			continue
		}
		content, ok := source.read(path)
		if len(observers) > 0 && observers[0] != nil {
			if evidence, observed := observers[0].evidence(path); observed {
				if evidence.err != nil {
					return nil, reads, evidence.err
				}
				reads++
				attribute := attributes[path]
				if !attribute.Binary && (attribute.Text || !evidence.binary) {
					if evidence.matched && len(evidence.terms) == 0 {
						matches = append(matches, gitutil.GrepMatch{Path: path})
					}
					for _, term := range evidence.terms {
						matches = append(matches, gitutil.GrepMatch{Path: path, Text: term})
					}
				}
				continue
			}
		}
		if !ok {
			continue
		}
		reads++
		stream := *prototype
		seen := make([]bool, len(terms))
		stream.emit = func(text string) {
			for index, matched := range termMatcher.match(text) {
				seen[index] = seen[index] || matched
			}
		}
		if _, err := stream.Write([]byte(content)); err != nil {
			return nil, reads, err
		}
		if err := stream.finish(); err != nil {
			return nil, reads, err
		}
		attribute := attributes[path]
		if !attribute.Binary && (attribute.Text || !stream.binary) {
			if stream.matched {
				matches = append(matches, gitutil.GrepMatch{Path: path})
			}
			for index, matched := range seen {
				if matched {
					matches = append(matches, gitutil.GrepMatch{Path: path, Text: terms[index]})
				}
			}
		}

	}
	return matches, reads, nil
}

