package sem

import (
	"context"
	"fmt"
	"strings"

	"github.com/entireio/entire-graph/internal/gitutil"
)

type searchPreselectionScan struct {
	patterns []string
	aliases  []string
	maxLines int
}

// searchPreselectionScanPlan is the bounded content plan shared by Git-backed
// and captured working-tree preselection. Ordinary terms share one 32-line
// sample; aliases either share a 32-line sample or get independent first-line
// passes so a common term cannot hide a later abbreviation.
func searchPreselectionScanPlan(q searchQuery) ([]searchPreselectionScan, error) {
	coalesced := len(q.inferredAbbreviations) > 0 && !searchGitAliasScansFit(q)
	primaryTerms := searchGitGrepPreselectionPatterns(q)
	if coalesced {
		primaryTerms = q.terms
	}
	primary := make([]string, 0, len(primaryTerms))
	for _, term := range primaryTerms {
		if !q.inferredAbbreviations[term] {
			primary = append(primary, term)
		}
	}
	plan := make([]searchPreselectionScan, 0, 1+len(q.inferredAbbreviations))
	if len(primary) > 0 {
		patterns := searchGitAliasPatternsForTerms(q, primary)
		if patterns == nil {
			return nil, fmt.Errorf("query requires content preselection")
		}
		plan = append(plan, searchPreselectionScan{patterns: patterns, maxLines: 32})
	}
	aliases := make([]string, 0, len(q.inferredAbbreviations))
	for _, term := range q.terms {
		if q.inferredAbbreviations[term] {
			aliases = append(aliases, term)
		}
	}
	if len(aliases) == 0 {
		return plan, nil
	}
	if coalesced {
		patterns := searchGitAliasPatternsForTerms(q, aliases)
		if patterns == nil {
			return nil, fmt.Errorf("query requires content preselection")
		}
		return append(plan, searchPreselectionScan{patterns: patterns, aliases: aliases, maxLines: 32}), nil
	}
	for _, alias := range aliases {
		patterns := searchGitAliasPatternsForTerms(q, []string{alias})
		if patterns == nil {
			return nil, fmt.Errorf("query requires content preselection")
		}
		plan = append(plan, searchPreselectionScan{patterns: patterns, aliases: []string{alias}, maxLines: 1})
	}
	return plan, nil
}

func capturedSearchPreselectionMatches(
	ctx context.Context,
	source sourceContext,
	tracked []string,
	q searchQuery,
	observer *capturePreselectionObserver,
) ([]gitutil.GrepMatch, int, int, error) {
	observer.activate()
	allowed := make(map[string]bool, len(source.paths))
	for _, path := range source.paths {
		allowed[path] = true
	}
	eligible := make([]string, 0, len(tracked))
	for _, path := range tracked {
		if allowed[path] {
			eligible = append(eligible, path)
		}
	}
	attributes, err := source.capturedDiffAttributes(ctx, eligible)
	if err != nil {
		return nil, 0, len(observer.passes), err
	}

	matches := make([]gitutil.GrepMatch, 0)
	reads := 0
	queryMatcher := newSearchQueryTermMatcher(q)
	for _, path := range tracked {
		if err := ctx.Err(); err != nil {
			return nil, reads, len(observer.passes), err
		}
		if !allowed[path] {
			continue
		}
		content, ok := source.read(path)
		if !ok {
			continue
		}
		reads++
		evidence, observed := observer.evidence(path)
		if !observed {
			return nil, reads, len(observer.passes), fmt.Errorf("captured preselection missing evidence for %s", path)
		}
		if evidence.err != nil {
			return nil, reads, len(observer.passes), evidence.err
		}
		attribute := attributes[path]
		if attribute.Binary || (!attribute.Text && evidence.binary) {
			continue
		}
		seen := make([]bool, len(q.terms))
		for passIndex, passEvidence := range evidence.passes {
			terms := passEvidence.terms
			if passEvidence.needsValidation {
				full := queryMatcher.match(content)
				confirmed := false
				for _, alias := range observer.passes[passIndex].aliases {
					for termIndex, term := range q.terms {
