					}
				}
				if !confirmed {
					continue
				}
				terms = full
			}
			for termIndex, matched := range terms {
				seen[termIndex] = seen[termIndex] || matched
			}
		}
		for termIndex, matched := range seen {
			if matched {
				matches = append(matches, gitutil.GrepMatch{Path: path, Text: q.terms[termIndex]})
			}
		}
	}
	return matches, reads, len(observer.passes), nil
}

func searchPreselectionAliasConfirmed(q searchQuery, aliases []string, text string) bool {
	lower := strings.ToLower(text)
	for _, alias := range aliases {
		if searchQueryTermMatches(q, text, lower, alias) {
			return true
		}
	}
