func (stream *captureMatchStream) drain(final bool) {
	for len(stream.buffer) > 0 {
		safe := len(stream.buffer) - stream.window
		if !final && safe < 0 {
			return
		}
		match := stream.matcher.FindStringIndex(stream.buffer)
		if match == nil {
			if final {
				stream.buffer = ""
			} else {
				stream.buffer = stream.buffer[safe:]
			}
			return
		}
		if !final && match[0] > safe {
			stream.buffer = stream.buffer[match[0]:]
			return
		}
		stream.lineMatched = true
		stream.matched = true
		stream.emit(stream.buffer[match[0]:match[1]])
		stream.buffer = stream.buffer[match[1]:]
	}
}

func (stream *captureMatchStream) finish() error {
	if err := stream.ctx.Err(); err != nil {
		return err
	}
	if stream.lines < stream.maxLines {
		stream.drain(true)
		if stream.lineMatched && stream.emitLine != nil {
			stream.emitLine(stream.line)
			stream.lines++
			stream.lineMatched = false
		}
	}
	return nil
}

type capturedMatchEvidence struct {
	matched bool
	terms   []string
	binary  bool
	err     error
	passes  []capturedSearchPassEvidence
}

type capturedSearchPassEvidence struct {
	terms           []bool
	needsValidation bool
}

type captureSearchPass struct {
	prototype captureMatchStream
	aliases   []string
}

// The observer retains at most one bit per query term per acquired file. In
// particular, arbitrary case variants on an oversized line cannot grow memory.
type capturePreselectionObserver struct {
	enabled   bool
	mu        sync.Mutex
	prototype captureMatchStream
	terms     []string
	matcher   searchTermMatcher
	records   map[string]capturedMatchEvidence
	query     searchQuery
	passes    []captureSearchPass
}

func newCapturePreselectionObserver(ctx context.Context, patterns, terms []string) (*capturePreselectionObserver, error) {
	stream, err := newCaptureMatchStream(ctx, patterns, 32, nil)
	if err != nil {
		return nil, err
	}
	return &capturePreselectionObserver{prototype: *stream, terms: append([]string(nil), terms...), matcher: newSearchTermMatcher(terms), records: map[string]capturedMatchEvidence{}}, nil
}

func newCaptureSearchPreselectionObserver(ctx context.Context, q searchQuery) (*capturePreselectionObserver, error) {
	observer := &capturePreselectionObserver{
		terms: append([]string(nil), q.terms...), matcher: newSearchTermMatcher(q.terms),
		records: map[string]capturedMatchEvidence{}, query: q,
	}
	plans, err := searchPreselectionScanPlan(q)
	if err != nil {
		return nil, err
	}
	for _, plan := range plans {
		stream, err := newCapturePatternStream(ctx, plan.patterns, plan.maxLines, nil)
		if err != nil {
			return nil, err
		}
		observer.passes = append(observer.passes, captureSearchPass{prototype: *stream, aliases: append([]string(nil), plan.aliases...)})
	}
	return observer, nil
}

type captureSearchPassWriter struct {
	streams []*captureMatchStream
}

func (writer *captureSearchPassWriter) Write(data []byte) (int, error) {
	for _, stream := range writer.streams {
		if _, err := stream.Write(data); err != nil {
			return 0, err
		}
	}
	return len(data), nil
}

