	for _, plan := range plans {
		stream, err := newCapturePatternStream(ctx, plan.patterns, plan.maxLines, nil)
		if err != nil {
			return nil, err
		}
		observer.passes = append(observer.passes, captureSearchPass{prototype: *stream, aliases: append([]string(nil), plan.aliases...)})
	}
	return observer, nil
}

type captureSearchPassWriter struct {
	streams []*captureMatchStream
}

func (writer *captureSearchPassWriter) Write(data []byte) (int, error) {
	for _, stream := range writer.streams {
		if _, err := stream.Write(data); err != nil {
			return 0, err
		}
	}
	return len(data), nil
}

