package sem

import (
	"encoding"
	"encoding/json"
	"fmt"
	"reflect"
	"sync"
	"unicode/utf8"
)

var (
	jsonMarshalerType = reflect.TypeOf((*json.Marshaler)(nil)).Elem()
	textMarshalerType = reflect.TypeOf((*encoding.TextMarshaler)(nil)).Elem()
	shapeOnce         sync.Once
	shapeErr          error
)

// validateExtractionRecord protects the private cache wire format from values
// that encoding/json would silently change. Shape validation is performed once
// per process; the normal cache path checks only the record's string leaves.
func validateExtractionRecord(record extractionRecord) error {
	shapeOnce.Do(func() {
		shapeErr = validateExtractionType(reflect.TypeOf(record), "record")
	})
	if shapeErr != nil {
		return shapeErr
	}
	for index, value := range record.RawImports {
		if err := validateExtractionIndexedString(value, "record.RawImports", index, ""); err != nil {
			return err
		}
	}
	if err := validateExtractionString(record.Language, "record.Language"); err != nil {
		return err
	}
	if err := validateExtractionString(record.Status.Code, "record.Status.Code"); err != nil {
		return err
	}
	if err := validateExtractionString(record.Status.Detail, "record.Status.Detail"); err != nil {
		return err
	}
	for index, declaration := range record.Declarations {
		if err := validateExtractionIndexedString(declaration.Kind, "record.Declarations", index, "Kind"); err != nil {
			return err
		}
		if err := validateExtractionIndexedString(declaration.Name, "record.Declarations", index, "Name"); err != nil {
			return err
		}
		if err := validateExtractionIndexedString(declaration.Signature, "record.Declarations", index, "Signature"); err != nil {
			return err
		}
		if err := validateExtractionIndexedString(declaration.BodyHash, "record.Declarations", index, "BodyHash"); err != nil {
			return err
		}
		if err := validateExtractionIndexedString(declaration.Fingerprint, "record.Declarations", index, "Fingerprint"); err != nil {
			return err
		}
		if err := validateExtractionIndexedString(declaration.ParamTypeText, "record.Declarations", index, "ParamTypeText"); err != nil {
			return err
		}
		if err := validateExtractionIndexedString(declaration.ReturnTypeText, "record.Declarations", index, "ReturnTypeText"); err != nil {
			return err
		}
		for parameterIndex, parameter := range declaration.ParameterNames {
			if err := validateExtractionParameterString(parameter, index, parameterIndex); err != nil {
				return err
			}
		}
	}
	return nil
}

func validateExtractionParameterString(value string, declarationIndex, parameterIndex int) error {
	if utf8.ValidString(value) {
		return nil
	}
	return fmt.Errorf("extraction record field record.Declarations[%d].ParameterNames[%d] contains invalid UTF-8", declarationIndex, parameterIndex)
}

func validateExtractionIndexedString(value, collection string, index int, field string) error {
	if utf8.ValidString(value) {
		return nil
	}
	if field == "" {
		return fmt.Errorf("extraction record field %s[%d] contains invalid UTF-8", collection, index)
	}
	return fmt.Errorf("extraction record field %s[%d].%s contains invalid UTF-8", collection, index, field)
}

func validateExtractionString(value, path string) error {
	if !utf8.ValidString(value) {
		return fmt.Errorf("extraction record field %s contains invalid UTF-8", path)
	}
	return nil
}

// validateExtractionValue is retained as a structural test seam. Production
// validation uses validateExtractionType once plus direct string checks above.
func validateExtractionValue(value reflect.Value, path string) error {
	if !value.IsValid() {
		return nil
	}
	return validateExtractionType(value.Type(), path)
}

func validateExtractionType(typ reflect.Type, path string) error {
	if typ.Implements(jsonMarshalerType) || typ.Implements(textMarshalerType) || (typ.Kind() != reflect.Pointer && reflect.PointerTo(typ).Implements(jsonMarshalerType)) || (typ.Kind() != reflect.Pointer && reflect.PointerTo(typ).Implements(textMarshalerType)) {
		return fmt.Errorf("extraction record field %s has a custom JSON/text marshaler", path)
	}
	switch typ.Kind() {
	case reflect.String, reflect.Bool, reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return nil
	case reflect.Struct:
		for index := 0; index < typ.NumField(); index++ {
			field := typ.Field(index)
			if field.PkgPath != "" {
				return fmt.Errorf("extraction record field %s.%s is unexported", path, field.Name)
			}
			if tag, ok := field.Tag.Lookup("json"); ok && tag != "" {
				return fmt.Errorf("extraction record field %s.%s has JSON tag %q", path, field.Name, tag)
			}
			if err := validateExtractionType(field.Type, path+"."+field.Name); err != nil {
				return err
			}
		}
		return nil
	case reflect.Slice:
		return validateExtractionType(typ.Elem(), path+"[]")
	default:
		return fmt.Errorf("extraction record field %s has unsupported JSON shape %s", path, typ)
	}
}
package sem

import (
	"encoding/json"
	"reflect"
	"sort"
	"strings"
	"testing"
)

type validationCustom string

func (validationCustom) MarshalJSON() ([]byte, error) { return []byte(`"custom"`), nil }

func validationFixtureRecord() extractionRecord {
	return extractionRecord{
		RawImports:       []string{"import/name"},
		RelationFamilies: extractionRawImports,
		Version:          extractionFormatVersion,
		Language:         "TypeScript",
		Status: ParseStatus{
			Code:   "E_PARSE",
			Detail: "bounded diagnostic",
		},
		Declarations: []extractedDeclaration{{
			Kind:           "function",
			Name:           "name",
			Signature:      "name(value: T): U",
			BodyHash:       "body",
			Fingerprint:    "fingerprint",
			ParameterNames: []string{"value"},
			ParamTypeText:  "value: T",
			ReturnTypeText: "U",
		}},
	}
}

func TestValidateExtractionRecordCoversEveryStringField(t *testing.T) {
	record := validationFixtureRecord()
	got := extractionStringPaths(reflect.TypeOf(record), "record")
	want := []string{
		"record.RawImports[]", "record.Language", "record.Status.Code", "record.Status.Detail",
		"record.Declarations[].Kind", "record.Declarations[].Name", "record.Declarations[].Signature",
		"record.Declarations[].BodyHash", "record.Declarations[].Fingerprint", "record.Declarations[].ParameterNames[]",
		"record.Declarations[].ParamTypeText", "record.Declarations[].ReturnTypeText",
	}
	sort.Strings(got)
	sort.Strings(want)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("string-field coverage changed: got %v, want %v; update validator and this test", got, want)
	}
	mutations := map[string]func(*extractionRecord){
		"raw import":              func(record *extractionRecord) { record.RawImports[0] = "\xff" },
		"language":                func(record *extractionRecord) { record.Language = "\xff" },
		"status code":             func(record *extractionRecord) { record.Status.Code = "\xff" },
		"status detail":           func(record *extractionRecord) { record.Status.Detail = "\xff" },
		"declaration kind":        func(record *extractionRecord) { record.Declarations[0].Kind = "\xff" },
		"declaration name":        func(record *extractionRecord) { record.Declarations[0].Name = "\xff" },
		"declaration signature":   func(record *extractionRecord) { record.Declarations[0].Signature = "\xff" },
		"declaration body hash":   func(record *extractionRecord) { record.Declarations[0].BodyHash = "\xff" },
		"declaration fingerprint": func(record *extractionRecord) { record.Declarations[0].Fingerprint = "\xff" },
		"parameter name":          func(record *extractionRecord) { record.Declarations[0].ParameterNames[0] = "\xff" },
		"parameter type":          func(record *extractionRecord) { record.Declarations[0].ParamTypeText = "\xff" },
		"return type":             func(record *extractionRecord) { record.Declarations[0].ReturnTypeText = "\xff" },
	}
	for name, mutate := range mutations {
		t.Run(name, func(t *testing.T) {
			record := validationFixtureRecord()
			mutate(&record)
			if err := validateExtractionRecord(record); err == nil || !strings.Contains(err.Error(), "invalid UTF-8") {
				t.Fatalf("validation error = %v, want invalid UTF-8", err)
			}
		})
	}
}

func extractionStringPaths(typ reflect.Type, path string) []string {
	switch typ.Kind() {
	case reflect.String:
		return []string{path}
	case reflect.Struct:
		var paths []string
		for index := 0; index < typ.NumField(); index++ {
			field := typ.Field(index)
			paths = append(paths, extractionStringPaths(field.Type, path+"."+field.Name)...)
		}
		return paths
	case reflect.Slice:
		return extractionStringPaths(typ.Elem(), path+"[]")
	default:
		return nil
	}
}

func TestValidateExtractionRecordAllowsNilAndEmptySlices(t *testing.T) {
	record := validationFixtureRecord()
	record.RawImports = nil
	record.Declarations = []extractedDeclaration{{ParameterNames: []string{}}}
	if err := validateExtractionRecord(record); err != nil {
		t.Fatal(err)
	}
	encoded, err := json.Marshal(record)
	if err != nil {
		t.Fatal(err)
	}
	var decoded extractionRecord
	if err := json.Unmarshal(encoded, &decoded); err != nil {
		t.Fatal(err)
	}
	if decoded.RawImports != nil || decoded.Declarations[0].ParameterNames == nil {
		t.Fatalf("nil/empty slice distinction changed: %#v", decoded)
	}
}

func TestValidateExtractionRecordValidPathAllocatesNothing(t *testing.T) {
	record := validationFixtureRecord()
	if err := validateExtractionRecord(record); err != nil {
		t.Fatal(err)
	}
	if allocations := testing.AllocsPerRun(100, func() {
		if err := validateExtractionRecord(record); err != nil {
			t.Fatal(err)
		}
	}); allocations != 0 {
		t.Fatalf("valid extraction validation allocations = %v, want zero", allocations)
	}
}

func TestValidateExtractionValueRejectsFutureLossyShapes(t *testing.T) {
	type tagged struct {
		Value string `json:"value,omitempty"`
	}
	// A future field with a custom marshaler must not silently change the cache
	// payload without an explicit wire-format review.
	funcValue := reflect.ValueOf(struct {
		Value map[string]string
	}{Value: map[string]string{"key": "value"}})
	if err := validateExtractionValue(reflect.ValueOf(tagged{}), "tagged"); err == nil || !strings.Contains(err.Error(), "JSON tag") {
		t.Fatalf("tagged shape error = %v", err)
	}
	if err := validateExtractionValue(funcValue, "map"); err == nil || !strings.Contains(err.Error(), "unsupported JSON shape") {
		t.Fatalf("map shape error = %v", err)
	}
	if err := validateExtractionValue(reflect.ValueOf(validationCustom("value")), "custom"); err == nil || !strings.Contains(err.Error(), "custom JSON/text marshaler") {
		t.Fatalf("custom marshaler error = %v", err)
	}
}
